#!/usr/bin/env bash
# shellcheck shell=bash
# scripts/tests/test-ci-lockfile-normalization.sh
set -euo pipefail

script_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"
# shellcheck disable=SC1091
source "$script_dir/update-ci-lockfiles.sh"

tmp_dir="$(mktemp -d)"
trap 'rm -rf "$tmp_dir"' EXIT

for python_version in 3.14 3.15; do
  lockfile="$tmp_dir/requirements-$python_version.txt"
  cat > "$lockfile" <<EOF
#
# This file is autogenerated by pip-compile with Python $python_version
# by the following command:
package==1.2.3 \\
    --hash=sha256:abc123
EOF

  normalize_lockfile_header "$lockfile"
  [[ "$(sed -n '2p' "$lockfile")" == "# This file is autogenerated by pip-compile" ]]
  [[ "$(sed -n '4p' "$lockfile")" == package==1.2.3* ]]
  [[ "$(sed -n '4p' "$lockfile")" == "package==1.2.3 \\" ]]
  [[ "$(sed -n '5p' "$lockfile")" == "    --hash=sha256:abc123" ]]
  before="$(cat "$lockfile")"
  if normalize_lockfile_header "$lockfile" 2>/dev/null; then
    echo "Expected normalized header to be rejected on a second pass" >&2
    exit 1
  fi
  [[ "$(cat "$lockfile")" == "$before" ]]
done

invalid="$tmp_dir/invalid.txt"
printf '#\n# unexpected header\npackage==1.2.3\n' > "$invalid"
if normalize_lockfile_header "$invalid" 2>/dev/null; then
  echo "Expected an unexpected header to be rejected" >&2
  exit 1
fi

echo "Lockfile header normalization tests passed."
